import { cn } from '@cascivo/core/pure'
import type { CSSProperties, HTMLAttributes } from 'react'
import styles from './skeleton.module.css'

export interface SkeletonProps extends HTMLAttributes<HTMLDivElement> {
  /**
   * Shape of the placeholder: `text` (stacked lines), `circle` (an avatar), `rect` (a
   * block).
   *
   * @defaultValue `text`
   * @see the component manifest
   */
  variant?: 'text' | 'circle' | 'rect'
  width?: string
  height?: string
  /**
   * Number of bars for the text variant; the last bar renders shorter
   *
   * @defaultValue `1`
   * @see the component manifest
   */
  lines?: number
}

export function Skeleton({
  variant = 'text',
  width,
  height,
  lines = 1,
  className,
  style,
  ...props
}: SkeletonProps) {
  const sizeVars = {
    ...(width !== undefined && { '--cascivo-skeleton-width': width }),
    ...(height !== undefined && { '--cascivo-skeleton-height': height }),
  } as CSSProperties

  return (
    <div
      aria-hidden="true"
      data-variant={variant}
      className={cn(styles['skeleton'], className)}
      style={{ ...sizeVars, ...style }}
      {...props}
    >
      {variant === 'text' &&
        Array.from({ length: lines }, (_, index) => (
          <span key={index} className={styles['line']} />
        ))}
    </div>
  )
}

@layer cascivo.component {
  .skeleton {
    &[data-variant='text'] {
      display: flex;
      flex-direction: column;
      gap: var(--cascivo-space-2);
      inline-size: var(--cascivo-skeleton-width, 100%);
    }

    &[data-variant='circle'] {
      inline-size: var(--cascivo-skeleton-width, var(--cascivo-space-10));
      block-size: var(--cascivo-skeleton-height, var(--cascivo-space-10));
      border-radius: var(--cascivo-radius-full);
    }

    &[data-variant='rect'] {
      inline-size: var(--cascivo-skeleton-width, 100%);
      block-size: var(--cascivo-skeleton-height, var(--cascivo-space-24));
      border-radius: var(--cascivo-radius-surface);
    }
  }

  .line {
    display: block;
    inline-size: 100%;
    block-size: var(--cascivo-skeleton-height, 1em);
    border-radius: var(--cascivo-radius-indicator);

    /* Multi-line paragraphs end on a shorter bar */
    &:last-child:not(:first-child) {
      inline-size: 60%;
    }
  }

  /* The shimmering surfaces. Position + clip here so the sheen overlay below has a
     containing block to travel inside; the resting appearance is a flat block, which is
     also exactly what a reduced-motion user sees. */
  .skeleton[data-variant='circle'],
  .skeleton[data-variant='rect'],
  .line {
    position: relative;
    overflow: hidden;
    background-color: var(--cascivo-color-border);
  }

  /* Sheen travels on an overlay rather than sliding `background-position` on the bar
     itself: `background-position` repaints the element every frame, while translating a
     pseudo-element stays on the compositor. */
  .skeleton[data-variant='circle']::after,
  .skeleton[data-variant='rect']::after,
  .line::after {
    content: '';
    position: absolute;
    inset: 0;
    translate: -100% 0;
    background-image: linear-gradient(
      90deg,
      transparent,
      var(--cascivo-color-bg-subtle),
      transparent
    );
  }

  /* Decorative loop — opt-in, so a user who expresses no preference gets no motion.
     A skeleton already reads as "loading" from its shape alone, so unlike Spinner there
     is nothing to preserve by slowing it instead of stopping it. */
  @media (prefers-reduced-motion: no-preference) {
    .skeleton[data-variant='circle']::after,
    .skeleton[data-variant='rect']::after,
    .line::after {
      animation: global(cascivo-shimmer) var(--cascivo-duration-loop) linear infinite;
    }
  }
}
